"""All commentary read from printed 237–250, joining continued paragraphs."""
from .common import SIDDUR, POEM
from .notes_minchah import note
B = 'urn:x-opensiddur:text:bible:psalms/'
ROOT = SIDDUR+'shabbat/kabbalat_shabbat'
DODI = POEM+'lecha_dodi'
NOTES = [
note(ROOT, 'the opening service on Friday evening, was introduced by the Kabbalists of the sixteenth century in Safed, Palestine. The six psalms, symbolizing the six working days of the week, were selected by Rabbi Moses Cordovero, whose brother-in-law Rabbi Solomon Alkabets composed the hymn welcoming the Sabbath bride (<tei:foreign xml:lang="he">לכה דודי</tei:foreign>). The initial letters of the six psalms (<tei:foreign xml:lang="he">ל, ש, י, מ, י, מ</tei:foreign>) have the numerical value of 430 which equals that of <tei:foreign xml:lang="he">נפש</tei:foreign> (“soul”). <tei:foreign xml:lang="he">מזמור לדוד</tei:foreign> (Psalm 29) contains the name of God eighteen times, a number corresponding to the eighteen blessings of the <tei:hi rend="italic">Shemoneh Esreh</tei:hi>.', lemma='קבלת שבת'),
note(B+'95', 'Psalm 95 is a call to worship the Creator of the world and Guardian of his people. It contains a warning against disobedience, and alludes to the fate of the rebellious Israelites in the wilderness (Exodus 17:7; Numbers 20:13).'),
note(B+'96', 'Psalm 96 contrasts God’s power and glory with the worthlessness of the heathen idols, and appeals to the nations to acknowledge God and to rejoice in the prospect of his righteous rule on earth.'),
note(B+'97', 'Psalm 97 is a mosaic of phrases borrowed from various Scriptural passages. It celebrates God’s manifestation of his sovereignty and calls his people to hate evil. All, even the gods existing in the minds of their worshipers, must do homage to the only true God. The Septuagint renders <tei:foreign xml:lang="he">אור זרוע לצדיק</tei:foreign> in the sense of <tei:foreign xml:lang="he">זרח . . . אור לישרים</tei:foreign> (Psalm 112:4): “Light dawns on the upright.”'),
note(B+'98', 'Psalm 98 is largely made up of quotations, yet it is a stirring song of joyous praise. <tei:foreign xml:lang="he">ירעם הים ומלאו</tei:foreign>, and the whole description of nature rejoicing at God’s coming to rule the world, is identical with Psalm 96:11–13. <tei:foreign xml:lang="he">נהרות ימחאו כף</tei:foreign> is descriptive of the crashing of the waves.'),
note(B+'99', 'Psalm 99 celebrates God’s universal sovereignty. His righteousness and faithfulness are manifested in the history of Israel. <tei:foreign xml:lang="he">הדום רגליו</tei:foreign> refers to the ark (I Chronicles 28:2).'),
note(B+'29', 'Psalm 29 describes the manifestation of God’s power in the thunderstorm and the flood, and ends with an assurance of his favor to his people.'),
note(ROOT+'/ana_bekhoach', 'a mystical meditation attributed to Rabbi Neḥunyah ben ha-Kanah, <tei:hi rend="italic">tanna</tei:hi> of the second century.', lemma='אנא בכח'),
note(DODI, 'was written by Rabbi Solomon Alkabets about the middle of the sixteenth century. The name of the author, <tei:foreign xml:lang="he">שלמה הלוי</tei:foreign>, is signed in the form of an acrostic at the beginning of the stanzas. This poem, “perhaps one of the finest pieces of religious poetry in existence,” became a favorite text of synagogal composers; a great number of melodies were set to it. Each stanza consists of four parts, three of which have the same rhyme, while the fourth part ends in the common rhyme <tei:foreign xml:lang="he">לה</tei:foreign> throughout the poem. There is scarcely a phrase in the poem which is not borrowed from the Bible. Combining the language of the Bible into a rare mosaic, the poet utilized phrases from Isaiah 52:2; 51:17; 60:1; Judges 5:12; Isaiah 60:1; 54:4; Psalm 42:12; Isaiah 14:32; Jeremiah 30:18, 16; Isaiah 49:19; 62:5; 54:3; 25:9. The Sabbath is personified here and compared to a bride, in the same sense as Israel is likened to a bride (Jeremiah 2:2). The poem gives expression to the hope of Israel in vivid figures of speech.', lemma='לכה דודי'),
note(DODI+'/1', 'refers to the talmudic explanation of the discrepancy between the two versions of the fourth commandment. In Exodus 20:8 the text reads: “Remember the Sabbath day,” and in Deuteronomy 5:12: “Observe the Sabbath day.” According to the Talmud (Shebuoth 20b), both words, <tei:foreign xml:lang="he">זכור</tei:foreign> and <tei:foreign xml:lang="he">שמור</tei:foreign>, were miraculously pronounced by God simultaneously.', lemma='שמור וזכור'),
note(B+'92', 'Psalm 92 was sung by the Levites in the Temple during the Sabbath offering. The psalmist reflects on the meaning of God’s works, a meaning which the foolish fail to perceive. The wicked seem to flourish only that they may be destroyed. The palm and cedar are long-lived and flourish during all seasons. They represent the enduring happiness of the faithful in contrast with the short-lived prosperity of the wicked.'),
note(ROOT+'/psalm_93', 'Psalm 93 speaks of God’s majesty and power. His control of the violent forces of nature represents his power over the mightiest enemies of Israel. God’s rule is the security of all moral order in the world.'),
note(ROOT+'/psalm_93', 'God’s moral laws are firmly established and unchangeable. Zion, his house, shall no longer be desecrated by heathen invaders. Rashi and others interpret this psalm in connection with the Messianic era.', lemma='עדתיך נאמנו'),
]

# Two paragraphs on Psalm 93 share one occurrence-specific annotation anchor.
NOTES[-2]["paras"].append(dict(text='<tei:label xml:lang="he">עדתיך נאמנו</tei:label> '+NOTES[-1]["paras"][0]["text"]))
NOTES.pop()
